const rules = { total: v => Number.isFinite(v) && v >= 0 };

const order = new Proxy(raw, {          // validated on read, not on arrival
  get(t, prop) {
    if (rules[prop] && !rules[prop](t[prop]))
      throw new RangeError(`${String(prop)} invalid for this use`);
    return t[prop];
  },
});
consume(order);                          // the gate is implicit in the access
